-- LOCAL ONLY. Read capabilities, no monthly validation writer or payment.
BEGIN READ ONLY;SET LOCAL search_path=pg_catalog;DO $hours_dependencies$ BEGIN
IF NOT EXISTS(SELECT 1 FROM pg_proc WHERE oid=to_regprocedure('folha_privado.ator()') AND proowner='postgres'::regrole AND prosecdef=true AND proconfig=ARRAY['search_path=pg_catalog'] AND encode(sha256(convert_to(replace(prosrc,chr(13),''),'UTF8')),'hex')='176c4fb030401fb45c89f3cd1616a9d26e9e15b691ff524a33dfc8d233c6b079' AND NOT EXISTS(SELECT 1 FROM aclexplode(coalesce(proacl,acldefault('f',proowner))) x WHERE x.grantee<>proowner )) THEN RAISE EXCEPTION 'HORAS_AUTHORIZATION_DEPENDENCY_DRIFT: folha_privado.ator()';END IF;
IF NOT EXISTS(SELECT 1 FROM pg_proc WHERE oid=to_regprocedure('folha_privado.obra(uuid,boolean)') AND proowner='postgres'::regrole AND prosecdef=true AND proconfig=ARRAY['search_path=pg_catalog'] AND encode(sha256(convert_to(replace(prosrc,chr(13),''),'UTF8')),'hex')='731f5289cd29bdb7f7d69723fabb76cbb8b8e577bb474c679f991c7271d9788e' AND NOT EXISTS(SELECT 1 FROM aclexplode(coalesce(proacl,acldefault('f',proowner))) x WHERE x.grantee<>proowner )) THEN RAISE EXCEPTION 'HORAS_AUTHORIZATION_DEPENDENCY_DRIFT: folha_privado.obra(uuid,boolean)';END IF;
IF NOT EXISTS(SELECT 1 FROM pg_proc WHERE oid=to_regprocedure('folha_privado.lock_dia(uuid,date)') AND proowner='postgres'::regrole AND prosecdef=true AND proconfig=ARRAY['search_path=pg_catalog'] AND encode(sha256(convert_to(replace(prosrc,chr(13),''),'UTF8')),'hex')='b29022304f316e25dd34bae7a1e1906a0dfd72bd041a1d658338cc8394745502' AND NOT EXISTS(SELECT 1 FROM aclexplode(coalesce(proacl,acldefault('f',proowner))) x WHERE x.grantee<>proowner )) THEN RAISE EXCEPTION 'HORAS_AUTHORIZATION_DEPENDENCY_DRIFT: folha_privado.lock_dia(uuid,date)';END IF;
IF NOT EXISTS(SELECT 1 FROM pg_proc WHERE oid=to_regprocedure('folha_privado.local(uuid,uuid,boolean)') AND proowner='postgres'::regrole AND prosecdef=true AND proconfig=ARRAY['search_path=pg_catalog'] AND encode(sha256(convert_to(replace(prosrc,chr(13),''),'UTF8')),'hex')='9eb2f0d8b7e52d5280f0798c48cb8ec84377281c1e13706bc066b1cf3765070b' AND NOT EXISTS(SELECT 1 FROM aclexplode(coalesce(proacl,acldefault('f',proowner))) x WHERE x.grantee<>proowner )) THEN RAISE EXCEPTION 'HORAS_AUTHORIZATION_DEPENDENCY_DRIFT: folha_privado.local(uuid,uuid,boolean)';END IF;
IF NOT EXISTS(SELECT 1 FROM pg_proc WHERE oid=to_regprocedure('public.fn_folha_contexto_v2(date,uuid)') AND proowner='postgres'::regrole AND prosecdef=true AND proconfig=ARRAY['search_path=pg_catalog'] AND encode(sha256(convert_to(replace(prosrc,chr(13),''),'UTF8')),'hex')='e5ca6e224708a655a9c778fa6a5701b39e6c0aab8dbf0a01a87ffb77d42ea095' AND NOT EXISTS(SELECT 1 FROM aclexplode(coalesce(proacl,acldefault('f',proowner))) x WHERE x.grantee<>proowner AND x.grantee<>'authenticated'::regrole)) THEN RAISE EXCEPTION 'HORAS_AUTHORIZATION_DEPENDENCY_DRIFT: public.fn_folha_contexto_v2(date,uuid)';END IF;
END $hours_dependencies$;DO $base$ BEGIN IF current_user<>'postgres' OR session_user<>'postgres' THEN RAISE EXCEPTION 'OWNER_REQUIRED';END IF;
IF NOT EXISTS(SELECT 1 FROM pg_proc WHERE oid=to_regprocedure('public.fn_folha_faltou_v2(text,jsonb,boolean,text)') AND proowner='postgres'::regrole AND prosecdef AND proconfig=ARRAY['search_path=pg_catalog'] AND provolatile='v' AND encode(sha256(convert_to(replace(prosrc,chr(13),''),'UTF8')),'hex')='094dc4ab55da2be8d497dc8d7b99f6fc15b24e76ca81e014c6f244d17425fe6e' AND (SELECT array_agg(x::text ORDER BY x::text) FROM unnest(proacl) x)=ARRAY['authenticated=X/postgres','postgres=X/postgres']) THEN RAISE EXCEPTION 'HORAS_READ_FUNCTION_DRIFT: public.fn_folha_faltou_v2(text,jsonb,boolean,text)';END IF;
IF NOT EXISTS(SELECT 1 FROM pg_proc WHERE oid=to_regprocedure('public.fn_folha_gestao_v2(text,jsonb,boolean,text)') AND proowner='postgres'::regrole AND prosecdef AND proconfig=ARRAY['search_path=pg_catalog'] AND provolatile='v' AND encode(sha256(convert_to(replace(prosrc,chr(13),''),'UTF8')),'hex')='97b41cd118aa9efee1fb960bf2d9d39585b3e4e7f525c624372e13adf374c856' AND (SELECT array_agg(x::text ORDER BY x::text) FROM unnest(proacl) x)=ARRAY['authenticated=X/postgres','postgres=X/postgres']) THEN RAISE EXCEPTION 'HORAS_READ_FUNCTION_DRIFT: public.fn_folha_gestao_v2(text,jsonb,boolean,text)';END IF;
END $base$;
DO $installed$ BEGIN IF current_user<>'postgres' OR session_user<>'postgres' THEN RAISE EXCEPTION 'OWNER_REQUIRED';END IF;
IF NOT EXISTS(SELECT 1 FROM pg_proc WHERE oid=to_regprocedure('public.fn_folha_relatorio_horas_v3(uuid,date,date,text,uuid)') AND proowner='postgres'::regrole AND prosecdef AND proconfig=ARRAY['search_path=pg_catalog'] AND provolatile='s' AND encode(sha256(convert_to(replace(prosrc,chr(13),''),'UTF8')),'hex')='b185fb111d185f19fceb2f0f2ffac1d473ae5b324a9a589b815304cd096f3b9d' AND (SELECT array_agg(x::text ORDER BY x::text) FROM unnest(proacl) x)=ARRAY['authenticated=X/postgres','postgres=X/postgres']) THEN RAISE EXCEPTION 'HORAS_READ_FUNCTION_DRIFT: public.fn_folha_relatorio_horas_v3(uuid,date,date,text,uuid)';END IF;
IF NOT EXISTS(SELECT 1 FROM pg_proc WHERE oid=to_regprocedure('public.fn_folha_conferencia_contexto_v3(uuid,date)') AND proowner='postgres'::regrole AND prosecdef AND proconfig=ARRAY['search_path=pg_catalog'] AND provolatile='s' AND encode(sha256(convert_to(replace(prosrc,chr(13),''),'UTF8')),'hex')='3c66b79ac1882a756ccd430fa403e5c4c195c195e8ddb77ae7699dc80b78ee6c' AND (SELECT array_agg(x::text ORDER BY x::text) FROM unnest(proacl) x)=ARRAY['authenticated=X/postgres','postgres=X/postgres']) THEN RAISE EXCEPTION 'HORAS_READ_FUNCTION_DRIFT: public.fn_folha_conferencia_contexto_v3(uuid,date)';END IF;
IF NOT EXISTS(SELECT 1 FROM pg_proc WHERE oid=to_regprocedure('public.fn_folha_horas_contexto_v3(date,uuid)') AND proowner='postgres'::regrole AND prosecdef AND proconfig=ARRAY['search_path=pg_catalog'] AND provolatile='s' AND encode(sha256(convert_to(replace(prosrc,chr(13),''),'UTF8')),'hex')='4162758ceba25fab4a3610746de8c92f8fb5548f9970d8a06997b3f8d0ca8f1b' AND (SELECT array_agg(x::text ORDER BY x::text) FROM unnest(proacl) x)=ARRAY['authenticated=X/postgres','postgres=X/postgres']) THEN RAISE EXCEPTION 'HORAS_READ_FUNCTION_DRIFT: public.fn_folha_horas_contexto_v3(date,uuid)';END IF;
END $installed$;
DO $data$ DECLARE r record;j jsonb;BEGIN IF current_user<>'postgres' OR session_user<>'postgres' THEN RAISE EXCEPTION 'OWNER_REQUIRED';END IF;
IF NOT EXISTS(SELECT 1 FROM pg_namespace WHERE nspname='primeline_horas_leituras_backup' AND nspowner='postgres'::regrole) OR EXISTS(SELECT 1 FROM pg_namespace n CROSS JOIN LATERAL aclexplode(coalesce(n.nspacl,acldefault('n',n.nspowner))) a WHERE n.nspname='primeline_horas_leituras_backup' AND a.grantee<>n.nspowner) OR EXISTS(SELECT 1 FROM pg_class c JOIN pg_namespace n ON n.oid=c.relnamespace CROSS JOIN LATERAL aclexplode(coalesce(c.relacl,acldefault('r',c.relowner))) a WHERE n.nspname='primeline_horas_leituras_backup' AND a.grantee<>c.relowner) OR EXISTS(SELECT 1 FROM pg_attribute a JOIN pg_class c ON c.oid=a.attrelid JOIN pg_namespace n ON n.oid=c.relnamespace WHERE n.nspname='primeline_horas_leituras_backup' AND a.attnum>0 AND NOT a.attisdropped AND a.attacl IS NOT NULL AND a.attacl<>'{}'::aclitem[]) THEN RAISE EXCEPTION 'HORAS_READ_BACKUP_NOT_PRIVATE';END IF;
FOR r IN SELECT * FROM primeline_horas_leituras_backup.dados LOOP EXECUTE format('SELECT coalesce(jsonb_agg(to_jsonb(x) ORDER BY to_jsonb(x)::text COLLATE "C"),''[]''::jsonb) FROM %s x',r.tabela::regclass) INTO j;IF j IS DISTINCT FROM r.linhas THEN RAISE EXCEPTION 'HORAS_READ_DATA_DRIFT';END IF;END LOOP;END $data$;
SELECT 'HORAS_READ_POSTCHECK_OK' resultado;COMMIT;
